def deployment_order(graph, roots):
    complete = set()
    active = set()
    order = []

    def visit(node):
        if node in active:
            raise DependencyCycleError(node)
        if node in complete:
            return
        active.add(node)
        for dependency in graph.get(node, []):
            visit(dependency)
        active.remove(node)
        complete.add(node)
        order.append(node)

    for root in roots:
        visit(root)
    return order
